window.MNLCP_DATA["glossary"] = {"_source": "Maui Nui Landscape Conservation Plan (DOFAW, version September 29, 2026), Terms and Definitions, pp. 120-123 (MNLCP 9-30-2026 FINAL.txt lines 4756-4912). All 28 plan terms, alphabetical as in the plan. Definitions are the plan's wording with light edits for readability and the MNLCP messaging rules (group names capitalized; 'team' for people, 'group' for species). Numbers are the plan's. 'aliases' are extra strings for sitewide hover tooltips; generic words (Recovery, Persistence, Maui Nui, Endangered/Threatened Species) carry no lowercase aliases so the tooltip script does not fire on every ordinary use. See content/notes/tools.md for edits made and open issues (e.g. the 155-PU plant priority example).", "terms": [{"term": "Action Prioritization Team", "definition": "The UH Mānoa–led team that addressed the “what to do” portion of the MNLCP. Using a modified Priority Threat Management process, the team worked with roughly 100 land managers and scientists to identify key threats, evaluate conservation actions, and estimate the costs and benefits of management strategies for Maui Nui’s at-risk species.", "see_also": ["Priority Threat Management (PTM)", "Persistence", "Integrated Multi-Scale Conservation Planning (IMCP)"], "aliases": ["Action Prioritization team", "action prioritization team"]}, {"term": "Adaptive Conservation Planner (ACP)", "definition": "Called the “Conservation Planner” for short, this is the spatially oriented, adaptive analytic tool that houses the MNLCP’s final spatial products—including recovery footprints and species, habitat, and threat metadata—and allows managers to revise strategies, develop annual work plans, and explore management scenarios.", "see_also": ["Recovery Footprint", "Priority Footprint", "Planning Unit (PU)"], "aliases": ["ACP", "Conservation Planner", "Adaptive Conservation Planner"]}, {"term": "Algorithmic Pathway", "definition": "One of the two process pathways used in spatial conservation planning, alongside the Expert-Led Pathway. Applied to taxonomic groups with numerous species and complex habitat or management considerations (Plants, Terrestrial arthropods, Terrestrial snails), it used the OptimTFE algorithm to generate candidate footprints across Maui Nui’s 1,400 planning units, which experts and managers then compared against criteria such as habitat quality, accessibility, and climate resilience.", "see_also": ["Expert-Led Pathway", "OptimTFE", "Planning Unit (PU)"], "aliases": ["algorithmic pathway", "algorithmic pathways", "Algorithmic Pathways"]}, {"term": "At-Risk Species", "definition": "A species identified by the Taxonomic Teams and other experts—using existing endangered species lists, Hawaiʻi’s State Wildlife Action Plan, and other sources—as likely to become extinct within the next 20 years without significant management intervention. The MNLCP identifies 442 at-risk species of birds, plants, invertebrates, and a bat, driven by factors such as low remaining population numbers, climate change, invasive species, and habitat loss.", "see_also": ["Taxonomic Team", "Endangered Species", "Threatened Species", "Hawaiʻi State Wildlife Action Plan (SWAP)"], "aliases": ["at-risk species", "species at risk"]}, {"term": "Chapter 195D, Hawaiʻi Revised Statutes", "definition": "Titled “Conservation of Aquatic Life, Wildlife, and Land Plants,” Chapter 195D is the State’s primary legal framework for protecting endangered and threatened species. It is administered by the Hawaiʻi Department of Land and Natural Resources (DLNR).", "see_also": ["Endangered Species", "Threatened Species", "Endangered Species Act (ESA)"], "aliases": ["Chapter 195D", "HRS 195D", "HRS Chapter 195D"]}, {"term": "Communications Team", "definition": "The team that develops and implements communication strategies to inform the public and others about the MNLCP and its accomplishments.", "see_also": ["Core Team"], "aliases": []}, {"term": "Core Team", "definition": "The DOFAW-led team that oversees MNLCP development, scheduling, and coordination of the other MNLCP teams.", "see_also": ["Implementation Team", "Communications Team", "Taxonomic Team"], "aliases": ["core team"]}, {"term": "Endangered Species", "definition": "A species formally listed under federal or State law as being in danger of extinction (shown as “E” in the plan’s ESA status tables), as distinct from a threatened species.", "see_also": ["Threatened Species", "Endangered Species Act (ESA)", "Chapter 195D, Hawaiʻi Revised Statutes"], "aliases": []}, {"term": "Endangered Species Act (ESA)", "definition": "The federal law under which species are formally listed as endangered or threatened. The plan tracks each at-risk species’ ESA status (E = endangered, T = threatened) throughout its taxonomic group tables.", "see_also": ["Endangered Species", "Threatened Species"], "aliases": ["ESA", "Endangered Species Act"]}, {"term": "Ex situ", "definition": "Conservation actions carried out outside a species’ natural habitat, such as captive rearing, captive breeding, or seed storage and banking.", "see_also": ["In situ"], "aliases": ["ex situ", "ex-situ"]}, {"term": "Expert-Led Pathway", "definition": "One of the two process pathways used in spatial conservation planning, alongside the Algorithmic Pathway. Used for taxonomic groups with fewer focal species or where expert knowledge was more informative than algorithmic methods (Forest birds, Seabirds, Waterbirds, Aquatic invertebrates), it had specialists identify priority areas directly through iterative web-map review.", "see_also": ["Algorithmic Pathway", "Taxonomic Team"], "aliases": ["expert-led pathway", "expert-led pathways", "Expert-Led Pathways"]}, {"term": "Hawaiʻi State Wildlife Action Plan (SWAP)", "definition": "One of the existing State planning documents the MNLCP draws on as a data source—alongside endangered species lists, conservation databases, and the literature—to help identify Maui Nui’s at-risk species.", "see_also": ["At-Risk Species"], "aliases": ["SWAP", "State Wildlife Action Plan", "Hawaiʻi’s State Wildlife Action Plan"]}, {"term": "Implementation Team", "definition": "The DOFAW-led team of land managers, planners, and decision-makers responsible for the “when to do it” guidance—translating the results of the spatial prioritization, action prioritization, and ecosystem prioritization efforts into a final, cohesive implementation plan, and overseeing development of the Managers’ Handbook.", "see_also": ["Core Team", "Integrated Multi-Scale Conservation Planning (IMCP)"], "aliases": ["implementation team"]}, {"term": "Integrated Multi-Scale Conservation Planning (IMCP)", "definition": "The MNLCP’s overarching planning approach, combining spatial prioritization, action prioritization, and ecosystem planning into a single, adaptive decision-support system. IMCP is state-led and expert-engaged, integrates conservation across biological, spatial, and temporal scales, and is oriented toward decision support and partnership rather than prescriptive mandates.", "see_also": ["Spatial Prioritization", "Priority Threat Management (PTM)", "Transparent, Flexible, Expert-engaged Systematic Conservation Planning (TFE-SCP)"], "aliases": ["IMCP", "Integrated Multi-Scale Conservation Planning"]}, {"term": "In situ", "definition": "Conservation actions carried out within a species’ natural habitat or wild population, such as predator-proof exclosures or direct protection and management of existing wild populations, as distinguished from ex situ actions performed away from the wild.", "see_also": ["Ex situ"], "aliases": ["in situ", "in-situ"]}, {"term": "Maui Nui", "definition": "The landscape covered by the plan, encompassing the islands of Maui, Molokaʻi, Lānaʻi, and Kahoʻolawe.", "see_also": [], "aliases": []}, {"term": "OptimTFE", "definition": "The site-selection spatial prioritization algorithm used within the TFE-SCP process. It generated hundreds of thousands of candidate recovery footprints, each meeting species-specific recovery or extinction-prevention targets, for comparison by species experts and land managers.", "see_also": ["Transparent, Flexible, Expert-engaged Systematic Conservation Planning (TFE-SCP)", "Algorithmic Pathway", "Recovery Footprint"], "aliases": ["optimTFE"]}, {"term": "Persistence", "definition": "The probability that a species group will have viable, self-sustaining populations over a 20-year period. It is the central metric used to evaluate the expected benefit of different conservation action strategies in the Priority Threat Management analysis.", "see_also": ["Priority Threat Management (PTM)", "Action Prioritization Team"], "aliases": []}, {"term": "Planning Unit (PU)", "definition": "The basic spatial unit used in the MNLCP’s spatial prioritization. The Maui Nui landscape was divided into a network of 1,400 medium-sized planning units, each roughly 2 km², delineated using watersheds, natural barriers, and elevational bands. Recovery and priority footprints are built up as collections of planning units, and each unit is sized to support a single population of an at-risk species. Finer-scale siting of specific actions within a planning unit (such as exactly where to outplant or fence) is then worked out by field teams using additional tools.", "see_also": ["Recovery Footprint", "Priority Footprint", "Spatial Prioritization"], "aliases": ["PU", "PUs", "planning unit", "planning units", "Planning Unit", "Planning Units"]}, {"term": "Priority Footprint", "definition": "The subset of a recovery footprint identifying the highest-priority planning units for near-term conservation action, which can be further narrowed into more focused annual work objectives. For example, the Plants recovery footprint’s 317 planning units include a priority footprint of 155 planning units.", "see_also": ["Recovery Footprint", "Planning Unit (PU)", "Adaptive Conservation Planner (ACP)"], "aliases": ["priority footprint", "priority footprints", "Priority Footprints"]}, {"term": "Priority Threat Management (PTM)", "definition": "A modified structured decision-making process used by the Action Prioritization Team to evaluate the expected costs, feasibility, and conservation benefits of management strategies. It assessed 27 conservation strategies (17 single-focus, 10 combinations) to identify the most cost-effective ways to raise species groups’ likelihood of persistence.", "see_also": ["Action Prioritization Team", "Persistence"], "aliases": ["PTM", "Priority Threat Management"]}, {"term": "Recovery", "definition": "Restoring an at-risk species to a healthy, self-sustaining population level. The MNLCP considers a species no longer at risk of extinction once it reaches its established recovery targets, even if it remains reliant on some ongoing conservation actions (“conservation reliant”).", "see_also": ["Recovery Footprint", "At-Risk Species"], "aliases": []}, {"term": "Recovery Footprint", "definition": "The spatially explicit planning units identified by the Spatial Prioritization Team and Taxonomic Teams as containing existing or restorable habitat needed for an at-risk species, or taxonomic group, to reach its recovery goals.", "see_also": ["Priority Footprint", "Planning Unit (PU)", "Recovery"], "aliases": ["recovery footprint", "recovery footprints", "Recovery Footprints"]}, {"term": "Spatial Prioritization", "definition": "The planning effort, implemented through the TFE-SCP process, that identifies where on the landscape to focus conservation efforts to meet explicit species recovery targets. It addresses the plan’s “where to manage” question.", "see_also": ["Spatial Prioritization Team", "Transparent, Flexible, Expert-engaged Systematic Conservation Planning (TFE-SCP)", "OptimTFE"], "aliases": ["spatial prioritization"]}, {"term": "Spatial Prioritization Team", "definition": "The USGS-led team responsible for the spatial prioritization effort, addressing “where to manage” for the recovery of Maui Nui’s at-risk species using the TFE-SCP process.", "see_also": ["Spatial Prioritization", "Transparent, Flexible, Expert-engaged Systematic Conservation Planning (TFE-SCP)"], "aliases": ["spatial prioritization team"]}, {"term": "Taxonomic Team", "definition": "DOFAW-led teams of species specialists that formed the backbone of the planning effort, providing qualitative input on species distributions, habitat quality, conservation needs, and management feasibility. Seven Taxonomic Teams were established (forest bird, seabird, waterbird, plant, snail, aquatic invertebrate, and terrestrial arthropod teams); the Hawaiian hoary bat is an eighth taxonomic group without its own dedicated team.", "see_also": ["At-Risk Species", "Expert-Led Pathway", "Core Team"], "aliases": ["Taxonomic Teams", "taxonomic team", "taxonomic teams", "taxon team", "taxon teams"]}, {"term": "Threatened Species", "definition": "A species formally listed under federal or State law as likely to become endangered in the foreseeable future (shown as “T” in the plan’s ESA status tables), as distinct from a species already listed as endangered. For example, ʻiʻiwi is federally listed as threatened, and nēnē is federally threatened while being state-listed as endangered.", "see_also": ["Endangered Species", "Endangered Species Act (ESA)", "Chapter 195D, Hawaiʻi Revised Statutes"], "aliases": []}, {"term": "Transparent, Flexible, Expert-engaged Systematic Conservation Planning (TFE-SCP)", "definition": "The USGS-developed spatial planning process used to implement spatial prioritization in the MNLCP. It is a comprehensive planning process with distinct stages, each supported by custom-built tools and involving input from biological experts and land managers, emphasizing transparency in decision-making, flexibility to adapt to different data and management contexts, and deep expert engagement throughout.", "see_also": ["Spatial Prioritization", "OptimTFE", "Adaptive Conservation Planner (ACP)"], "aliases": ["TFE-SCP", "TFE SCP", "TFE-SCP process"]}]};
